1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"slices"
10		"strconv"
11		"unicode/utf8"
12	)
13	
14	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
15	// truncated JSON, trailing data after the object, an unknown version,
16	// missing, mistyped, unknown, or duplicated fields, a null where version,
17	// tip, height, hash, parent, or a transaction identifier is required,
18	// heights that do not ascend consecutively from 1, an empty or duplicated
19	// hash, a broken parent link, a version-2 timestamp that is missing or
20	// neither null nor a non-negative integer, a hash, parent, or transaction
21	// identifier whose JSON string carries invalid UTF-8 bytes or unpaired or
22	// misordered Unicode surrogate escapes, or a tip that disagrees with the
23	// block list. A rejected restore never changes the index.
24	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
25	
26	const (
27		// snapshotVersion1 is the timestamp-less layout. It stays readable
28		// indefinitely; its blocks restore with missing timestamps.
29		snapshotVersion1 = 1
30		// snapshotVersion2 adds a required timestamp field to every block:
31		// either a non-negative Unix-seconds integer or null for missing time.
32		snapshotVersion2 = 2
33	)
34	
35	// snapshotDoc is the wire form of an exported main chain. Both layout
36	// versions share one shape: Version selects whether every block carries its
37	// Timestamp field.
38	type snapshotDoc struct {
39		Version int64           `json:"version"`
40		Tip     int64           `json:"tip"`
41		Blocks  []snapshotBlock `json:"blocks"`
42	}
43	
44	// snapshotBlock is the wire form of one block, shared by both versions.
45	// Height, hash, parent, and the transaction list follow the same rules in
46	// either layout. The timestamp is version 2 only and carried as a raw
47	// literal: nil is omitted altogether (version 1), "null" marks a missing
48	// time, and integer bytes render the Unix-seconds value (version 2). It
49	// stays the final field in every layout.
50	type snapshotBlock struct {
51		Height    int64           `json:"height"`
52		Hash      string          `json:"hash"`
53		Parent    string          `json:"parent"`
54		Txs       []string        `json:"txs"`
55		Timestamp json.RawMessage `json:"timestamp,omitempty"`
56	}
57	
58	// Export writes the current main chain to w as a JSON snapshot: a single
59	// object with version, tip, and the blocks ordered by ascending height, each
60	// carrying its transactions in order. The same main chain always produces
61	// the same bytes, regardless of the reorg, restore, or query history that
62	// led to it. Only blocks in effect at export time appear; nothing the index
63	// once held and later dropped is included.
64	//
65	// A chain whose blocks all lack timestamps keeps the original version-1
66	// layout, byte for byte. As soon as any block carries a timestamp the
67	// document is version 2 and every block includes a timestamp field: a
68	// non-negative integer or null for a missing timestamp.
69	//
70	// Export observes one complete chain state and never modifies the index.
71	// The chain is copied under the lock and serialized afterwards, so queries
72	// and appends proceed while the stream is still being written. A write
73	// failure is reported and leaves the index untouched.
74	func (index *Index) Export(w io.Writer) error {
75		doc := index.snapshotChain()
76		raw, err := json.Marshal(doc)
77		if err != nil {
78			panic(err) // snapshot docs only contain marshalable fields
79		}
80		n, err := w.Write(raw)
81		if err != nil {
82			return fmt.Errorf("indexroom: export snapshot: %w", err)
83		}
84		if n != len(raw) {
85			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
86		}
87		return nil
88	}
89	
90	// snapshotChain copies the current main chain into the export wire
91	// form: blocks by ascending height, each with its transactions copied in
92	// original order. This is the single place that turns stored blocks into the
93	// shared document fields, so both layout versions keep identical rules for
94	// height, hash, parent, and the transaction list; the only version-dependent
95	// field is the timestamp literal.
96	//
97	// The version is selected from the same chain copy. Any block carrying a
98	// timestamp — even a zero — makes the document version 2, after which every
99	// block gets a timestamp field, null where its time is missing; a chain
100	// whose blocks all lack times stays version 1 with no timestamp field.
101	func (index *Index) snapshotChain() snapshotDoc {
102		index.mu.Lock()
103		defer index.mu.Unlock()
104		version := int64(snapshotVersion1)
105		for height := int64(1); height <= index.Tip; height++ {
106			if index.Blocks[height].Time != nil {
107				version = snapshotVersion2
108				break
109			}
110		}
111		doc := snapshotDoc{
112			Version: version,
113			Tip:     index.Tip,
114			Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
115		}
116		for height := int64(1); height <= index.Tip; height++ {
117			block := index.Blocks[height]
118			txs := make([]string, len(block.Txs))
119			copy(txs, block.Txs)
120			entry := snapshotBlock{
121				Height: block.Height,
122				Hash:   block.Hash,
123				Parent: block.Parent,
124				Txs:    txs,
125			}
126			if version == snapshotVersion2 {
127				entry.Timestamp = snapshotTimestampLiteral(block.Time)
128			}
129			doc.Blocks = append(doc.Blocks, entry)
130		}
131		return doc
132	}
133	
134	// snapshotMissingTimestamp is the raw JSON literal written for a block whose
135	// time is missing in a version-2 document.
136	var snapshotMissingTimestamp = json.RawMessage("null")
137	
138	// snapshotTimestampLiteral renders a stored block time as its version-2
139	// timestamp literal: null for a missing time, otherwise its non-negative
140	// Unix-seconds value as a bare integer. Stored times are guaranteed
141	// non-negative by Append, Reorg, and Restore validation.
142	func snapshotTimestampLiteral(time *int64) json.RawMessage {
143		if time == nil {
144			return snapshotMissingTimestamp
145		}
146		return json.RawMessage(strconv.AppendInt(nil, *time, 10))
147	}
148	
149	// restoreAppliedHookLocked is a test-only rendezvous invoked from Restore
150	// once the snapshot chain has fully replaced the old main chain, while
151	// index.mu is still held and before the call returns. It is nil in
152	// production; restore regression tests park a successful restore here with
153	// the new chain already in effect, so a QueryTimeStats issued at that
154	// instant is forced to wait and, once it runs, must observe the complete
155	// new chain.
156	var restoreAppliedHookLocked func(newTip int64)
157	
158	// Restore replaces the whole main chain with the snapshot read from r. The
159	// input must be exactly one snapshot object, optionally followed by
160	// whitespace; every block is validated — including heights ascending from 1,
161	// non-empty unique hashes, and parent linkage — before anything is applied.
162	// The first block's parent is exempt from linkage: it names the chain start
163	// and need not be indexed.
164	//
165	// The replacement takes effect as one complete operation: on success the
166	// index holds exactly the snapshot chain with no leftover heights or hashes,
167	// and on any failure — a read error or an invalid block discovered at the
168	// very end — the current chain and every previously issued cursor remain as
169	// they were. The stream is consumed and validated before the lock is taken,
170	// so the index stays queryable and appendable while the restore is reading.
171	//
172	// After a successful restore, cursors issued earlier by this same index keep
173	// working wherever the pinned range still matches and the tip still covers
174	// it; otherwise continuations fail with ErrQueryChanged as usual.
175	func (index *Index) Restore(r io.Reader) error {
176		tip, blocks, err := parseSnapshot(r)
177		if err != nil {
178			return err
179		}
180		stored := make(map[int64]Block, len(blocks))
181		byHash := make(map[string]int64, len(blocks))
182		for _, block := range blocks {
183			stored[block.Height] = block
184			byHash[block.Hash] = block.Height
185		}
186		index.mu.Lock()
187		index.Blocks = stored
188		index.ByHash = byHash
189		index.Tip = tip
190		if restoreAppliedHookLocked != nil {
191			restoreAppliedHookLocked(tip)
192		}
193		index.mu.Unlock()
194		return nil
195	}
196	
197	// snapshotReader mediates between the snapshot's io.Reader and the JSON
198	// decoder so a fault the reader reports mid-document cannot be mistaken for a
199	// truncated document.
200	//
201	// json.Decoder turns a clean io.EOF after a partial JSON value into
202	// io.ErrUnexpectedEOF, and its token/peek path also drops any error that
203	// arrives together with the final bytes of a chunk. Either behavior makes a
204	// reader-reported io.ErrUnexpectedEOF — bare or wrapped — indistinguishable
205	// from an honestly truncated stream, and can hide the fault altogether.
206	//
207	// snapshotReader therefore observes every underlying read: a normal io.EOF
208	// passes through untouched, while any other error is remembered in fault and,
209	// when it arrived together with bytes, withheld until the following read. The
210	// decoder consumes the delivered bytes first and then receives the fault as a
211	// separate error-only read, where it cannot be swallowed. The fault is sticky
212	// afterwards, so a reader that oddly resumes after failing can never let the
213	// snapshot be applied once a failure has already been reported.
214	type snapshotReader struct {
215		r       io.Reader
216		fault   error // first non-EOF error reported by r, if any
217		pending bool  // fault is due on the next read
218	}
219	
220	func (s *snapshotReader) Read(p []byte) (int, error) {
221		if s.pending {
222			s.pending = false
223			return 0, s.fault
224		}
225		if s.fault != nil {
226			return 0, s.fault
227		}
228		n, err := s.r.Read(p)
229		if err == nil || errors.Is(err, io.EOF) {
230			return n, err
231		}
232		if s.fault == nil {
233			s.fault = err
234		}
235		if n > 0 {
236			s.pending = true
237			return n, nil
238		}
239		return 0, err
240	}
241	
242	// parseSnapshot reads and fully validates one snapshot document. It returns
243	// the tip height and the validated blocks in ascending height order.
244	func parseSnapshot(r io.Reader) (int64, []Block, error) {
245		// A fault the underlying reader reports mid-document — including one
246		// delivered together with usable bytes — is observed via snapshotReader
247		// rather than inferred from the JSON decoder, which would conflate it with
248		// a clean io.EOF on truncated input.
249		reader := &snapshotReader{r: r}
250		dec := json.NewDecoder(reader)
251		// classify maps a decoder failure onto the snapshot error model, but a
252		// fault observed on the underlying reader always wins: the decoder turns a
253		// clean io.EOF after truncated input into io.ErrUnexpectedEOF, so the
254		// presence of a real reader fault is the only reliable way to tell a read
255		// failure from an honestly truncated document. Field context carried by
256		// err (for example which field was being read) is preserved, and the
257		// recorded fault stays in the chain even when the decoder reports a
258		// separate content error from bytes already buffered.
259		classify := func(err error) error {
260			if reader.fault == nil {
261				return classifySnapshotErr(err)
262			}
263			if !errors.Is(err, reader.fault) {
264				err = fmt.Errorf("%w: %v", reader.fault, err)
265			}
266			return fmt.Errorf("indexroom: read snapshot: %w", err)
267		}
268		// reject reports a content error found in bytes already decoded, unless
269		// the underlying reader has already reported a fault: a stream that
270		// failed cannot be known to be complete, so the read failure takes
271		// precedence over any content error the same batch of bytes exposed —
272		// even over a complete, otherwise valid snapshot. Only a fault already
273		// observed wins; content errors found before the reader has failed are
274		// reported as-is, without reading ahead to look for one.
275		reject := func(err error) error {
276			if reader.fault != nil {
277				return fmt.Errorf("indexroom: read snapshot: %w", reader.fault)
278			}
279			return err
280		}
281		tok, err := dec.Token()
282		if err != nil {
283			return 0, nil, classify(err)
284		}
285		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
286			return 0, nil, reject(invalidSnapshot("snapshot must be a single JSON object"))
287		}
288	
289		// Top-level fields are captured raw so blocks can be parsed with the
290		// strict schema matching the declared version, whatever the field order,
291		// and so null can be told apart from a zero value.
292		var (
293			rawVersion, rawTip   json.RawMessage
294			rawBlocks            json.RawMessage
295			haveVersion, haveTip bool
296			haveBlocks           bool
297			seen                 = map[string]bool{}
298		)
299		for dec.More() {
300			key, err := snapshotKey(dec)
301			if err != nil {
302				return 0, nil, classify(err)
303			}
304			if seen[key] {
305				return 0, nil, reject(invalidSnapshot("duplicate field %q", key))
306			}
307			seen[key] = true
308			switch key {
309			case "version":
310				if err := dec.Decode(&rawVersion); err != nil {
311					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
312				}
313				haveVersion = true
314			case "tip":
315				if err := dec.Decode(&rawTip); err != nil {
316					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
317				}
318				haveTip = true
319			case "blocks":
320				if err := dec.Decode(&rawBlocks); err != nil {
321					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
322				}
323				haveBlocks = true
324			default:
325				return 0, nil, reject(invalidSnapshot("unknown field %q", key))
326			}
327		}
328		if _, err := dec.Token(); err != nil { // closing '}'
329			return 0, nil, classify(err)
330		}
331		// Only whitespace may follow the snapshot object. A reader fault that
332		// arrived together with the document's final bytes is held back by
333		// snapshotReader and surfaces here, ahead of any content validation below:
334		// once the stream failed, the document cannot be known to be complete, so
335		// the read failure takes precedence even when the buffered bytes already
336		// contain trailing data or a complete object.
337		if reader.fault != nil {
338			return 0, nil, fmt.Errorf("indexroom: read snapshot: %w", reader.fault)
339		}
340		if _, err := dec.Token(); err != io.EOF {
341			if err == nil {
342				// The read that fetched the trailing bytes may itself have
343				// reported a fault; that failure still outranks the extra data.
344				return 0, nil, reject(invalidSnapshot("trailing data after the snapshot object"))
345			}
346			return 0, nil, classify(err)
347		}
348	
349		if !haveVersion {
350			return 0, nil, invalidSnapshot("missing field %q", "version")
351		}
352		if !haveTip {
353			return 0, nil, invalidSnapshot("missing field %q", "tip")
354		}
355		if !haveBlocks {
356			return 0, nil, invalidSnapshot("missing field %q", "blocks")
357		}
358		version, err := snapshotInt64(rawVersion, "version")
359		if err != nil {
360			return 0, nil, err
361		}
362		tip, err := snapshotInt64(rawTip, "tip")
363		if err != nil {
364			return 0, nil, err
365		}
366		if version != snapshotVersion1 && version != snapshotVersion2 {
367			return 0, nil, invalidSnapshot("unsupported version %d", version)
368		}
369	
370		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
371		blocks, err := parseSnapshotBlocks(blockDec, version)
372		if err != nil {
373			return 0, nil, err
374		}
375		if _, err := blockDec.Token(); err != io.EOF {
376			if err == nil {
377				return 0, nil, invalidSnapshot("trailing data after the blocks array")
378			}
379			return 0, nil, classifySnapshotErr(err)
380		}
381	
382		lastHeight := int64(0)
383		if len(blocks) > 0 {
384			lastHeight = blocks[len(blocks)-1].Height
385		}
386		if tip != lastHeight {
387			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
388		}
389		return tip, blocks, nil
390	}
391	
392	// parseSnapshotBlocks reads the blocks array value, validating heights,
393	// hashes, parent links, and (for version 2) timestamps as it goes.
394	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
395		tok, err := dec.Token()
396		if err != nil {
397			return nil, classifySnapshotErr(err)
398		}
399		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
400			return nil, invalidSnapshot("field %q must be an array", "blocks")
401		}
402		blocks := []Block{}
403		seenHash := map[string]bool{}
404		for dec.More() {
405			var block Block
406			if version == snapshotVersion2 {
407				block, err = parseSnapshotBlockV2(dec)
408			} else {
409				block, err = parseSnapshotBlock(dec)
410			}
411			if err != nil {
412				return nil, err
413			}
414			want := int64(len(blocks) + 1)
415			if block.Height != want {
416				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
417			}
418			if block.Hash == "" {
419				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
420			}
421			if seenHash[block.Hash] {
422				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
423			}
424			seenHash[block.Hash] = true
425			// The first block's parent names the chain start and is exempt from
426			// linkage; every later block must point at its predecessor.
427			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
428				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
429			}
430			blocks = append(blocks, block)
431		}
432		if _, err := dec.Token(); err != nil { // closing ']'
433			return nil, classifySnapshotErr(err)
434		}
435		return blocks, nil
436	}
437	
438	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
439	// fields height, hash, parent, and txs.
440	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
441		var block Block
442		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs")
443		if err != nil {
444			return block, err
445		}
446		return finishSnapshotBlock(fields)
447	}
448	
449	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
450	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
451	// null or a non-negative integer; the block returns a nil time for null.
452	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
453		var block Block
454		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs", "timestamp")
455		if err != nil {
456			return block, err
457		}
458		if _, ok := fields["timestamp"]; !ok {
459			return block, invalidSnapshot("block is missing field %q", "timestamp")
460		}
461		block, err = finishSnapshotBlock(fields)
462		if err != nil {
463			return block, err
464		}
465		t, err := parseSnapshotTimestamp(fields["timestamp"])
466		if err != nil {
467			return Block{}, err
468		}
469		block.Time = t
470		return block, nil
471	}
472	
473	// readSnapshotBlockObject reads one block object and captures each known
474	// field's raw value. Fields are decoded only after the whole object is read,
475	// so a null can be rejected per field and a txs element error can name the
476	// block's height whatever order the fields arrive in.
477	func readSnapshotBlockObject(dec *json.Decoder, known ...string) (map[string]json.RawMessage, error) {
478		tok, err := dec.Token()
479		if err != nil {
480			return nil, classifySnapshotErr(err)
481		}
482		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
483			return nil, invalidSnapshot("block must be a JSON object")
484		}
485		fields := map[string]json.RawMessage{}
486		for dec.More() {
487			key, err := snapshotKey(dec)
488			if err != nil {
489				return nil, classifySnapshotErr(err)
490			}
491			if _, dup := fields[key]; dup {
492				return nil, invalidSnapshot("duplicate block field %q", key)
493			}
494			if !slices.Contains(known, key) {
495				return nil, invalidSnapshot("unknown block field %q", key)
496			}
497			var raw json.RawMessage
498			if err := dec.Decode(&raw); err != nil {
499				return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
500			}
501			fields[key] = raw
502		}
503		if _, err := dec.Token(); err != nil { // closing '}'
504			return nil, classifySnapshotErr(err)
505		}
506		return fields, nil
507	}
508	
509	// finishSnapshotBlock decodes the shared block fields from their raw values,
510	// requiring height, hash, parent, and txs and rejecting null for each.
511	func finishSnapshotBlock(fields map[string]json.RawMessage) (Block, error) {
512		var block Block
513		for _, field := range []string{"height", "hash", "parent", "txs"} {
514			if _, ok := fields[field]; !ok {
515				return block, invalidSnapshot("block is missing field %q", field)
516			}
517		}
518		var err error
519		if block.Height, err = snapshotInt64(fields["height"], "height"); err != nil {
520			return block, err
521		}
522		if block.Hash, err = snapshotString(fields["hash"], "hash", block.Height); err != nil {
523			return block, err
524		}
525		if block.Parent, err = snapshotString(fields["parent"], "parent", block.Height); err != nil {
526			return block, err
527		}
528		txs, err := parseSnapshotTxs(json.NewDecoder(bytes.NewReader(fields["txs"])), block.Height)
529		if err != nil {
530			return block, err
531		}
532		block.Txs = txs
533		return block, nil
534	}
535	
536	// snapshotInt64 decodes one required integer field, rejecting null rather
537	// than letting it pass as zero.
538	func snapshotInt64(raw json.RawMessage, field string) (int64, error) {
539		if isSnapshotNull(raw) {
540			return 0, invalidSnapshot("field %q must not be null", field)
541		}
542		var v int64
543		if err := json.Unmarshal(raw, &v); err != nil {
544			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
545		}
546		return v, nil
547	}
548	
549	// snapshotString decodes one required string field, rejecting null rather
550	// than letting it pass as the empty string. The raw literal is also checked
551	// for invalid UTF-8 bytes and unpaired or misordered \uXXXX surrogate
552	// escapes, which the decoder would otherwise silently rewrite to U+FFFD;
553	// height identifies the block the field belongs to in the error.
554	func snapshotString(raw json.RawMessage, field string, height int64) (string, error) {
555		if isSnapshotNull(raw) {
556			return "", invalidSnapshot("field %q must not be null", field)
557		}
558		var s string
559		if err := json.Unmarshal(raw, &s); err != nil {
560			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
561		}
562		if !validSnapshotString(raw) {
563			return "", invalidSnapshot("block at height %d: field %q has invalid UTF-8 or unpaired surrogate escapes", height, field)
564		}
565		return s, nil
566	}
567	
568	// isSnapshotNull reports whether a raw field value is the JSON null literal.
569	func isSnapshotNull(raw json.RawMessage) bool {
570		return string(raw) == "null"
571	}
572	
573	// validSnapshotString reports whether raw is a JSON string literal whose
574	// content is valid UTF-8 and whose \uXXXX escapes contain no unpaired or
575	// misordered surrogates. The JSON decoder accepts both defects silently,
576	// rewriting the bad parts to U+FFFD, which could merge distinct identifiers;
577	// the raw bytes are checked here before the decoded value is trusted. A
578	// genuine U+FFFD — written literally or as a \ufffd escape — is valid
579	// UTF-8 and passes.
580	func validSnapshotString(raw json.RawMessage) bool {
581		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
582			return false
583		}
584		body := raw[1 : len(raw)-1]
585		for i := 0; i < len(body); {
586			b := body[i]
587			switch {
588			case b == '\\':
589				if i+1 >= len(body) {
590					return false
591				}
592				if body[i+1] != 'u' {
593					i += 2 // \", \\, \/, \b, \f, \n, \r, \t
594					continue
595				}
596				code, ok := snapshotHex4(body, i+2)
597				if !ok {
598					return false
599				}
600				i += 6
601				switch {
602				case code >= 0xD800 && code <= 0xDBFF:
603					// A high surrogate is only valid as the first half of a
604					// pair; the low half must follow immediately as an escape.
605					if i+6 > len(body) || body[i] != '\\' || body[i+1] != 'u' {
606						return false
607					}
608					low, ok := snapshotHex4(body, i+2)
609					if !ok || low < 0xDC00 || low > 0xDFFF {
610						return false
611					}
612					i += 6
613				case code >= 0xDC00 && code <= 0xDFFF:
614					return false // a low surrogate cannot appear on its own
615				}
616			case b < utf8.RuneSelf:
617				i++
618			default:
619				// DecodeRune returns RuneError with size 1 for invalid
620				// encoding; a genuine U+FFFD decodes with size 3.
621				r, size := utf8.DecodeRune(body[i:])
622				if r == utf8.RuneError && size <= 1 {
623					return false
624				}
625				i += size
626			}
627		}
628		return true
629	}
630	
631	// snapshotHex4 reads four hexadecimal digits starting at b[i].
632	func snapshotHex4(b []byte, i int) (rune, bool) {
633		if i+4 > len(b) {
634			return 0, false
635		}
636		var v rune
637		for _, c := range b[i : i+4] {
638			var d byte
639			switch {
640			case '0' <= c && c <= '9':
641				d = c - '0'
642			case 'a' <= c && c <= 'f':
643				d = c - 'a' + 10
644			case 'A' <= c && c <= 'F':
645				d = c - 'A' + 10
646			default:
647				return 0, false
648			}
649			v = v*16 + rune(d)
650		}
651		return v, true
652	}
653	
654	// parseSnapshotTimestamp reads one timestamp value: null for a missing
655	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
656	// distinct from null.
657	func parseSnapshotTimestamp(raw json.RawMessage) (*int64, error) {
658		var t *int64
659		if err := json.Unmarshal(raw, &t); err != nil {
660			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
661		}
662		if t != nil && *t < 0 {
663			return nil, invalidSnapshot("timestamp must not be negative")
664		}
665		return t, nil
666	}
667	
668	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
669	// identifiers exactly as written. A null element is rejected, naming the
670	// block's height and the element's zero-based position, and so is an
671	// element whose raw string carries invalid UTF-8 bytes or unpaired or
672	// misordered surrogate escapes.
673	func parseSnapshotTxs(dec *json.Decoder, height int64) ([]string, error) {
674		tok, err := dec.Token()
675		if err != nil {
676			return nil, classifySnapshotErr(err)
677		}
678		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
679			return nil, invalidSnapshot("field %q must be an array of strings", "txs")
680		}
681		txs := []string{}
682		for dec.More() {
683			var raw json.RawMessage
684			if err := dec.Decode(&raw); err != nil {
685				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
686			}
687			if isSnapshotNull(raw) {
688				return nil, invalidSnapshot("block at height %d: txs element %d must not be null", height, len(txs))
689			}
690			var tx string
691			if err := json.Unmarshal(raw, &tx); err != nil {
692				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
693			}
694			if !validSnapshotString(raw) {
695				return nil, invalidSnapshot("block at height %d: field %q element %d has invalid UTF-8 or unpaired surrogate escapes", height, "txs", len(txs))
696			}
697			txs = append(txs, tx)
698		}
699		if _, err := dec.Token(); err != nil { // closing ']'
700			return nil, classifySnapshotErr(err)
701		}
702		return txs, nil
703	}
704	
705	// snapshotKey reads the next object key and returns the decoder's error
706	// unwrapped so each caller can classify it against its own input source.
707	func snapshotKey(dec *json.Decoder) (string, error) {
708		tok, err := dec.Token()
709		if err != nil {
710			return "", err
711		}
712		key, ok := tok.(string)
713		if !ok {
714			return "", invalidSnapshot("object key must be a string")
715		}
716		return key, nil
717	}
718	
719	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
720	func invalidSnapshot(format string, args ...any) error {
721		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
722	}
723	
724	// classifySnapshotErr maps decoder failures onto the snapshot error model:
725	// malformed JSON, wrong value types, and truncation are snapshot errors,
726	// while anything else is an underlying read failure reported as-is.
727	func classifySnapshotErr(err error) error {
728		var syntaxErr *json.SyntaxError
729		var typeErr *json.UnmarshalTypeError
730		switch {
731		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
732			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
733		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
734			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
735		default:
736			return fmt.Errorf("indexroom: read snapshot: %w", err)
737		}
738	}
739

