194	// bucketBoundary returns Start + step*index, saturated at MaxInt64 instead
195	// of overflowing. Callers cut saturated and trailing boundaries back to the
196	// requested window end.
197	func bucketBoundary(start, step, index int64) int64 {
198		offset := saturatingMul(step, index)
199		if offset > 1<<63-1-start {
200			return 1<<63 - 1
201		}
202		return start + offset
203	}
