205	// saturatingMul multiplies non-negative a and b, saturating at MaxInt64.
206	func saturatingMul(a, b int64) int64 {
207		if a == 0 || b == 0 {
208			return 0
209		}
210		if a > (1<<63-1)/b {
211			return 1<<63 - 1
212		}
213		return a * b
214	}
